fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    let len = list.len();
    // Preconditions: non-empty list, and 0 < n < len
    debug_assert!(len > 0, "list must be non-empty");
    debug_assert!(n > 0 && n < len, "n must be a strict interior index");

    // Allocate a new Vec with the same capacity as the input list.
    let mut new_list = Vec::with_capacity(len);

    // 1. Extend with the tail segment: list[n..len]
    new_list.extend_from_slice(&list[n..]);

    // 2. Extend with the head segment: list[0..n]
    new_list.extend_from_slice(&list[..n]);

    new_list
}

